class Solution:
    def buildGrid(self, m: int, n: int) -> List[str]:
        return ['.' * n] + ['#' * (n - 1) + '.' for _ in range(m - 1)]

c.cpp:
class Solution {
public:
    vector<string> buildGrid(int m, int n) {
        vector<string> g;
        g.push_back(string(n, '.'));
        for (int i = 1; i < m; i++) g.push_back(string(n - 1, '#') + '.');
        return g;
    }
};

c.java:
class Solution {
    public List<String> buildGrid(int m, int n) {
        List<String> g = new ArrayList<>();
        char[] top = new char[n];
        Arrays.fill(top, '.');
        g.add(new String(top));
        for (int i = 1; i < m; i++) {
            char[] row = new char[n];
            Arrays.fill(row, '#');
            row[n - 1] = '.';
            g.add(new String(row));
        }
        return g;
    }
}

