class Solution {
    public List<String> buildGrid(int m, int n) {
        List<String> g = new ArrayList<>();
        for (int i = 0; i < m - 1; i++) {
            char[] row = new char[n];
            row[0] = '.';
            Arrays.fill(row, 1, n, '#');
            g.add(new String(row));
        }
        char[] last = new char[n];
        Arrays.fill(last, '.');
        g.add(new String(last));
        return g;
    }
}

